import {StrictMode} from "react";import {act,fireEvent,render,screen} from "@testing-library/react";import {expect,test} from "vitest";import {TicketTabs} from "./TicketTabs";import {createFeed,moveTab,sharedName} from "./activityModel";import {capabilities,SharedTitle,navigateAction} from "./visual";import {Demo} from "./Demo";
test("Activity zachowuje szkic, DOM i scrollTop, a sprząta subskrypcję",async()=>{const feed=createFeed(),view=render(<TicketTabs ticketId={42} feed={feed}/>);expect(feed.active(42)).toBe(0);await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Komentarze"})));const input=screen.getByRole("textbox"),scroller=screen.getByLabelText("Przewijana lista");fireEvent.change(input,{target:{value:"Mój szkic"}});scroller.scrollTop=60;expect(feed.active(42)).toBe(1);await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Historia"})));expect(screen.queryByRole("textbox")).toBeNull();expect(input).toBeInTheDocument();expect(feed.active(42)).toBe(0);feed.publish(42);await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Komentarze"})));expect(screen.getByRole("textbox")).toBe(input);expect(input).toHaveValue("Mój szkic");expect(scroller.scrollTop).toBe(60);expect(screen.getByText("Zdarzenia: 1")).toBeVisible();expect(feed.active(42)).toBe(1);view.unmount();expect(feed.active(42)).toBe(0);});
test("klawiatura przełącza tab i fokus z zawijaniem",async()=>{const feed=createFeed();render(<TicketTabs ticketId={42} feed={feed}/>);const details=screen.getByRole("tab",{name:"Szczegóły"});details.focus();await act(async()=>fireEvent.keyDown(details,{key:"ArrowLeft"}));expect(screen.getByRole("tab",{name:"Historia"})).toHaveFocus();expect(screen.getByRole("tab",{name:"Historia"})).toHaveAttribute("aria-selected","true");await act(async()=>fireEvent.keyDown(screen.getByRole("tab",{name:"Historia"}),{key:"Home"}));expect(details).toHaveFocus();expect(screen.getAllByRole("tabpanel")).toHaveLength(1);expect(details).toHaveAttribute("tabindex","0");expect(screen.getByRole("tab",{name:"Komentarze"})).toHaveAttribute("tabindex","-1");});
test("zmiana tożsamości ticketu resetuje szkic i połączenie",async()=>{const feed=createFeed(),view=render(<TicketTabs key={42} ticketId={42} feed={feed}/>);await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Komentarze"})));fireEvent.change(screen.getByRole("textbox"),{target:{value:"Stary szkic"}});await act(async()=>view.rerender(<TicketTabs key={7} ticketId={7} feed={feed}/>));expect(feed.active(42)).toBe(0);await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Komentarze"})));expect(screen.getByRole("textbox")).toHaveValue("");expect(feed.active(7)).toBe(1);});
test("StrictMode i ponowne ujawnienia nie dublują aktywnych subskrypcji",async()=>{const feed=createFeed(),view=render(<StrictMode><TicketTabs ticketId={42} feed={feed}/></StrictMode>);for(let i=0;i<3;i++){await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Komentarze"})));expect(feed.active(42)).toBe(1);await act(async()=>fireEvent.click(screen.getByRole("tab",{name:"Historia"})));expect(feed.active(42)).toBe(0);}view.unmount();expect(feed.active(42)).toBe(0);});
test("przypięty runtime ma Activity, a fallback działa bez ViewTransition",()=>{expect(capabilities).toEqual({activity:true,viewTransition:false,transitionTypes:false});render(<SharedTitle id={42}><h2>Tytuł</h2></SharedTitle>);expect(screen.getByRole("heading")).toHaveTextContent("Tytuł");expect(sharedName(42)).not.toBe(sharedName(7));expect(moveTab("history","ArrowRight")).toBe("details");});
test("nawigacja bez eksportu ViewTransition nadal zmienia widok",async()=>{render(<Demo/>);expect(screen.getByText(/wersja bez animacji/)).toBeVisible();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Ticket 42"})));expect(screen.getByRole("heading",{name:"Ticket 42"})).toBeVisible();await act(async()=>fireEvent.click(screen.getByRole("button",{name:"Wróć do listy"})));expect(screen.getByRole("button",{name:"Ticket 42"})).toBeVisible();});
test("navigateAction wykonuje aktualizację także bez opcjonalnych typów przejść",async()=>{let called=0;await act(async()=>navigateAction(()=>{called++;}));expect(called).toBe(1);});

